    name = _expect(tokens, TokenType.IDENTIFIER).value
    type_token = _expect(tokens, TokenType.KEYWORD)
    if type_token.value not in {"INTEGER", "TEXT", "BOOLEAN"}:
        raise SQLSyntaxError(f"Invalid column type: {type_token.value}")
    column_type = ColumnType[type_token.value]
    return ColumnDef(name, column_type)

def _parse_column_list(tokens):
    _expect(tokens, TokenType.OPERATOR)  # '('
    columns = []
    while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ')':
        columns.append(_expect(tokens, TokenType.IDENTIFIER).value)
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ',':
            _expect(tokens, TokenType.OPERATOR)  # ','
        else:
            break
    _expect(tokens, TokenType.OPERATOR)  # ')'
    return tuple(columns)

def _parse_values_list(tokens):
    _expect(tokens, TokenType.OPERATOR)  # '('
    values = []
    while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ')':
        if tokens[0].type == TokenType.INTEGER:
            values.append(int(_expect(tokens, TokenType.INTEGER).value))
        elif tokens[0].type == TokenType.STRING:
            values.append(_expect(tokens, TokenType.STRING).value)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "TRUE":
            _expect(tokens, TokenType.KEYWORD)
            values.append(True)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "FALSE":
            _expect(tokens, TokenType.KEYWORD)
            values.append(False)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
            _expect(tokens, TokenType.KEYWORD)
            values.append(None)
        else:
            raise SQLSyntaxError(f"Unexpected token in VALUES list: {tokens[0].type}")
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ',':
            _expect(tokens, TokenType.OPERATOR)  # ','
        else:
            break
