    return tuple(values)

def _parse_comparison(tokens):
    left = _parse_primary(tokens)
    op_token = _expect(tokens, TokenType.OPERATOR)
    if op_token.value not in COMPARISON_OPS:
        raise SQLSyntaxError(f"Invalid comparison operator: {op_token.value}")
    right = _parse_primary(tokens)
    return Comparison(op_token.value, left, right)

