    operand = _parse_primary(tokens)
    is_token = _expect(tokens, TokenType.KEYWORD)
    if is_token.value != "IS":
        raise SQLSyntaxError(f"Expected IS, got {is_token.value}")
    null_token = _expect(tokens, TokenType.KEYWORD)
    negated = False
    if null_token.value == "NOT":
        null_token = _expect(tokens, TokenType.KEYWORD)
        negated = True
    if null_token.value != "NULL":
        raise SQLSyntaxError(f"Expected NULL, got {null_token.value}")
    return IsNull(operand, negated)

def _parse_primary(tokens):
    if tokens[0].type == TokenType.OPERATOR and tokens[0].value == '(':  # Parentheses
        _expect(tokens, TokenType.OPERATOR)  # '('
        expr = parse_expression(tokens)
        _expect(tokens, TokenType.OPERATOR)  # ')'
        return expr
    elif tokens[0].type == TokenType.INTEGER:
        return Literal(int(_expect(tokens, TokenType.INTEGER).value))
    elif tokens[0].type == TokenType.STRING:
        return Literal(_expect(tokens, TokenType.STRING).value)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value in {"TRUE", "FALSE", "NULL"}:
        value = _expect(tokens, TokenType.KEYWORD).value
        if value == "TRUE":
            return Literal(True)
        elif value == "FALSE":
            return Literal(False)
        elif value == "NULL":
            return Literal(None)
    elif tokens[0].type == TokenType.IDENTIFIER:
        return ColumnRef(_expect(tokens, TokenType.IDENTIFIER).value)
    else:
        raise SQLSyntaxError(f"Unexpected token in primary: {tokens[0].type}")

