                columns.append(_expect(tokens, TokenType.IDENTIFIER).value)
                if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ',':
                    _expect(tokens, TokenType.OPERATOR)  # ','
                else:
                    break
            columns = tuple(columns)
        _expect(tokens, TokenType.KEYWORD)  # FROM
        table = _expect(tokens, TokenType.IDENTIFIER).value
        where = None
        if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
            _expect(tokens, TokenType.KEYWORD)  # WHERE
            where = parse_expression(tokens)
        stmt = SelectStmt(table, columns, where)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "DELETE":
